package vn.iotstar.security;import org.springframework.security.core.userdetails.*;import org.springframework.stereotype.Service;import vn.iotstar.repository.UserRepository;@Service public class CustomUserDetailsService implements UserDetailsService{public CustomUserDetailsService(UserRepository repo){this.repo=repo;}final UserRepository repo;public UserDetails loadUserByUsername(String username){return repo.findByUsername(username).map(CustomUserDetails::new).orElseThrow(()->new UsernameNotFoundException("Username không tồn tại"));}}
